import { CARD_FRAMES, frameFor, frameVars } from './frame-assets.js';
import { BOARD_THEMES, BOARD_KEYS, boardOptions, boardVariant } from '../boards/catalog.js';
import { mountScene, currentScene } from '../boards/scene.js';
import { ANIME_PRESETS } from '../cards/anime-presets.js';
import {TG_HEROES} from '../cards/tokyo-ghoul.js';
import { gearCost, isFruitUser } from '../engine/one-piece.js';
import { LEAF, STRAW_HATS, TOKYO_GHOUL, PLAYABLE_FACTIONS, FACTION_POOLS, FACTION_LISTS, copyLimit } from '../cards/index.js';
import { allCards, getCard } from '../engine/registry.js';
import { checkDeck, singleDeckProblem } from '../cards/deck-check.js';
import { actingPlayer, applyAction, createGame, getLegalActions } from '../engine/engine.js';
import { allKeywords, effectiveAttack } from '../engine/core.js';
import { chooseAction } from '../ai/greedy.js';

const $ = s => document.querySelector(s);
const scrollRoot=()=>document.getElementById('app');
let scrollingUntil=0,renderAfterScroll=null,restoringScroll=false;
function resetPageScroll(){scrollRoot().scrollTop=0;}
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon = {collection:'▦',decks:'▤',battle:'⚔',boards:'✧',rules:'◈'};
const KEY='anime-clash-v1';
const load = (key,fallback) => {try {return JSON.parse((localStorage.getItem(`${KEY}-${key}`)??'null').replaceAll('Hidden Leaf Village','Naruto').replaceAll('Straw Hat Pirates','One Piece')) ?? fallback;}catch{return fallback;}};
const save = (key,data) => {try{localStorage.setItem(`${KEY}-${key}`,JSON.stringify(data));}catch{toast('Browser storage is full. Your current session still works.');}};
let faction=load('faction',LEAF);
if(!PLAYABLE_FACTIONS.includes(faction))faction=LEAF;
const deckBooks=load('decks',{});
let deck=deckBooks[faction]??(faction===LEAF?load('deck',FACTION_LISTS[LEAF]):FACTION_LISTS[faction]);
if(!Array.isArray(deck)||deck.some(id=>!FACTION_POOLS[faction].includes(id)))deck=[...FACTION_LISTS[faction]];
let presets=ANIME_PRESETS[faction],collection=FACTION_POOLS[faction].map(getCard),deckListOpen=window.innerWidth>640,zoomUnit=null;
let tgHero=load('tg-hero','kaneki');
function selectedTGHero(){return deck.map(getCard).find(c=>c.investigatorHero)?.investigatorHero??(TG_HEROES[tgHero]&&!TG_HEROES[tgHero].card?tgHero:'kaneki');}
function heroChooser(){if(faction!==TOKYO_GHOUL)return '';const choice=selectedTGHero(),info=TG_HEROES[choice],named=!!info.card;return `<div class="tg-hero-choice"><label>YOUR HERO<select id="tg-hero" ${named?'disabled':''}>${(named?[choice]:['kaneki','touka','tsukiyama','nishiki','investigator']).map(k=>`<option value="${k}" ${k===choice?'selected':''}>${esc(TG_HEROES[k].name)}</option>`).join('')}</select></label><p>${named?'Hero card included in your 30-card deck; 29 cards begin in the draw pile.':info.path==='ghoul'?`Ghoul Hero · ${esc(info.kagune)} Kagune · Cannibalism & Kakuja`:'Investigator Hero · Quinque Arsenal · 5 starting Armor'}</p><small>${info.path==='ghoul'?'Kagune exhausts at zero Durability. Feed your Ghouls to control Hunger.':'Add Arima, Amon or Akira to select a named Investigator Hero.'}</small></div>`;}
const FACTION_META={
 [TOKYO_GHOUL]:{badge:'◈',short:'Tokyo Ghoul',title:'Hunger in the Shadows',headline:'Embrace your <em>Hunger.</em>',anime:'TOKYO GHOUL',ink:'喰種',description:'Choose a Ghoul or Investigator Hero. Master your Kagune, or hunt with the CCG.',portrait:'art/tokyo-ghoul/kaneki.webp',rival:'art/tokyo-ghoul/arima.webp',back:'art/tokyo-ghoul/masked.webp',hero:'tg_predatory_instinct',troop:'Minions',spell:'Spells',exp:'03'},
 [LEAF]:{badge:'🍃',short:'Naruto',title:'The Will of Fire',headline:'The Will of <em>Fire.</em>',anime:'NARUTO',ink:'木ノ葉',description:'Build your team. Master your Jutsu. Write your own shinobi story.',portrait:'art/identity/naruto-hero.jpg',rival:'art/identity/naruto-hero.jpg',back:'art/identity/naruto-back.jpg',hero:'shadow_clone_technique',troop:'Shinobi',spell:'Jutsu',exp:'01'},
 [STRAW_HATS]:{badge:'☠',short:'One Piece',title:'Set Sail for Adventure',headline:'Set sail for <em>Adventure.</em>',anime:'ONE PIECE',ink:'海賊王',description:'Gather your Nakama. Awaken your powers. Chase the freedom of the open sea.',portrait:'art/identity/one-piece-hero.jpg',rival:'art/identity/one-piece-hero.jpg',back:'art/identity/one-piece-back.jpg',hero:'op_nakama',troop:'Pirates',spell:'Spells',exp:'02'},
};
const meta=(f=faction)=>FACTION_META[f];
function persistDeck(){deckBooks[faction]=[...deck];save('decks',deckBooks);if(faction===LEAF)save('deck',deck);}
function setFaction(f){if(!PLAYABLE_FACTIONS.includes(f))return;persistDeck();faction=f;save('faction',f);presets=ANIME_PRESETS[f];collection=FACTION_POOLS[f].map(getCard);deck=[...(deckBooks[f]??Object.values(presets)[0])];filter='all';search='';mana='all';selected=null;zoom=null;zoomUnit=null;render();}
function factionPicker(){return `<div class="faction-picker" role="group" aria-label="Choose faction">${PLAYABLE_FACTIONS.map(f=>`<button data-faction="${f}" class="${f===faction?'picked':''}" aria-pressed="${f===faction}"><img src="${meta(f).portrait}" alt=""><span>${meta(f).badge} ${f}<small>${meta(f).anime} · 45 cards</small></span></button>`).join('')}</div>`;}
let page='collection', search='', filter='all', mana='all', rarity='all', sort='number', selected=null, zoom=null;
const boardPreferences=load('board-preferences',{});let boardOrientation=load('board-orientation','auto'),boardSound=load('board-sound',false),boardDebug=false,boardQuality=load('board-quality','auto'),assetTab='boards';
let state=load('match',null), aiTimer=null, toastTimer=null, mulligan=[], placement='end';
if(state && (!Array.isArray(state.players) || state.players.length!==2 || !state.rules || !Array.isArray(state.queue) || state.players.some(p=>p.factions?.length!==1||!PLAYABLE_FACTIONS.includes(p.factions[0])||!Array.isArray(p.board)||!Array.isArray(p.hand))))state=null;

const counts=()=>deck.reduce((o,id)=>(o[id]=(o[id]??0)+1,o),{});
function toast(message){clearTimeout(toastTimer);let el=$('#toast');if(!el){el=document.createElement('div');el.id='toast';el.setAttribute('role','status');document.body.append(el);}el.textContent=message;el.classList.add('show');toastTimer=setTimeout(()=>el.classList.remove('show'),3000);}
function header(){return `<aside class="sidebar"><a class="brand" href="#collection" aria-label="Anime Clash home"><span class="brand-mark">忍</span><span>ANIME<span>CLASH<span class="brand-dot">.</span></span></span></a><div class="season">THE FIRST CHAPTER <i>01</i></div><nav>${[['collection','Collection'],['decks','Deck builder'],['battle','Battle'],['boards','Boards'],['rules','How to play']].map(([id,label])=>`<a href="#${id}" class="nav-item ${page===id?'active':''}"><span>${icon[id]}</span>${label}${id==='collection'?'<small>135</small>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="leaf-badge">🍃</div><strong>${meta().title}</strong><p>Three factions. Your adventure.</p><span class="version"><i></i> EXPANSION 01</span></div></aside><header class="topbar"><span class="breadcrumb">PLAY / <b>${page==='decks'?'DECK BUILDER':page==='battle'?'BATTLE':page==='rules'?'FIELD GUIDE':page==='boards'?'BOARDS':'COLLECTION'}</b></span><span class="top-right"><span class="status-dot"></span> All cards unlocked <span class="avatar">忍</span></span></header>`;}
function card(c,{builder=false,compact=false,inst=null,valid=false}={}) {
 const frameMeta=frameFor(c);const n=counts()[c.id]??0,type=c.type==='minion'?'minion':c.quickPlay?'quickplay':'spell',frame=c.legendary?`legendary-${c.type}`:`painted-${type}`;
 const df=c.devilFruitUser?'Devil Fruit User · Cannot consume another Fruit':c.devilFruitSpell?'Permanent Fruit · Non-users only':'';
 return `<article class="card ${c.legendary?'legendary':''} ${compact?'compact':''} ${valid?'playable':''}" ${inst?`data-hand="${inst.uid}" tabindex="0" role="button" aria-label="Play ${esc(c.name)}"`:''}><div class="realm-card new-skin ${c.type==='minion'||c.frameType==='minion'?'minion-frame':'spell-frame'}" style="${frameVars(frameMeta)}">
 <div class="card-art" style="background-image:url('${c.image??'art/hidden-leaf/shadow_clone.webp'}')"></div><div class="rules-parchment"><p>${richText(c.text)}</p></div><img class="realm-frame" src="${frameMeta.src}" alt="" draggable="false" loading="lazy"><span class="mana-orb">${c.investigatorHero?'H':c.cost}</span><span class="faction-sigil" title="${esc(c.faction)}">${meta(c.faction)?.badge??'✦'}</span><h3><span class="card-name-text">${esc(c.name)}</span></h3><div class="card-kind">${c.legendary?'LEGENDARY ':''}${c.token?'TOKEN':c.heroSpell?'HERO SPELL':c.devilFruitSpell?'DEVIL FRUIT':c.type==='minion'?c.faction===LEAF?'SHINOBI':c.faction===TOKYO_GHOUL?c.species:'PIRATE':c.quickPlay?'QUICK PLAY':c.weather?'WEATHER':c.fire?'FIRE SPELL':'SPELL'}</div>${['minion','weapon'].includes(c.type)?`<span class="card-atk">${c.attack}</span><span class="card-hp" title="${c.type==='weapon'?'Durability':'Health'}">${c.health??c.durability}</span>`:''}<button class="art-inspect" data-zoom="${c.id}" aria-label="Inspect ${esc(c.name)}">+</button></div>${df?`<div class="fruit-label" title="${esc(df)}">${c.devilFruitUser?'◈ FRUIT USER':'✦ PERMANENT FRUIT'}</div>`:''}${builder?`<div class="card-edit"><button data-remove="${c.id}" aria-label="Remove ${esc(c.name)}" ${n===0?'disabled':''}>−</button><span>${n} / ${copyLimit(c.id)}</span><button data-add="${c.id}" aria-label="Add ${esc(c.name)}" ${n>=copyLimit(c.id)||deck.length>=30?'disabled':''}>+</button></div>`:''}</article>`;
}

function hero(){return `<section class="hero" style="--faction-portrait:url('${new URL(meta().portrait,document.baseURI).href}')"><div class="hero-ink">${meta().ink}</div><div class="hero-content"><div class="eyebrow"><span></span>${meta().anime} · COLLECTION ${meta().exp}</div><h1>${meta().headline}</h1><p>${meta().description}</p><div class="hero-buttons"><button class="primary" data-nav="decks">Build your deck <span>→</span></button><button class="ghost" data-nav="battle">Enter the battlefield →</button></div></div><div class="hero-label"><span>${meta().badge}</span><div>${faction.toUpperCase()}<small>ONE FACTION. YOUR STRATEGY.</small></div></div></section>`;}

function filters(){return `<div class="collection-tools"><div class="tabs" role="group" aria-label="Card type">${[['all','All cards'],['minion',meta().troop],['spell',meta().spell],...(faction===TOKYO_GHOUL?[['trap','Traps'],['weapon','Quinques'],['hero','Heroes']]:[]),['legendary','Legendaries'],['tokens','Tokens']].map(([id,n])=>`<button class="${filter===id?'selected':''}" data-filter="${id}">${n}</button>`).join('')}</div><div class="search-box"><span>⌕</span><input id="search" type="search" placeholder="Find a card or ability…" aria-label="Find a card or ability" value="${esc(search)}"><kbd>/</kbd></div></div><div class="sub-tools"><div class="mana-filter"><span>MANA</span><button data-mana="all" class="${mana==='all'?'on':''}">All</button>${[0,1,2,3,4,5,6,7].map(n=>`<button data-mana="${n}" class="${String(n)===mana?'on':''}">${n===7?'7+':n}</button>`).join('')}</div><label class="sort-label">Sort by <select id="sort" aria-label="Sort cards"><option value="number" ${sort==='number'?'selected':''}>Collection order</option><option value="mana" ${sort==='mana'?'selected':''}>Mana cost</option><option value="name" ${sort==='name'?'selected':''}>Name</option></select></label></div>`;}
function filtered(){let list=(filter==='tokens'?allCards().filter(c=>c.token&&c.faction===faction):collection).filter(c=>(filter==='all'||filter==='tokens'||(filter==='legendary'?c.legendary:c.type===filter))&&(mana==='all'||(mana==='7'?c.cost>=7:c.cost===Number(mana)))&&`${c.name} ${c.text} ${c.legendary?'Legendary':''} ${c.weather?'Weather':''} ${c.fire?'Fire':''} ${c.devilFruitSpell?'Permanent Devil Fruit':''} ${c.luffy?'Luffy Gear Shift':''}`.toLowerCase().includes(search.toLowerCase()));if(sort==='mana')list.sort((a,b)=>a.cost-b.cost||a.name.localeCompare(b.name));if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));return list;}
function collectionHTML(builder=false){const list=filtered();return `${factionPicker()}${!builder?hero():''}<section class="collection-heading"><div><div class="eyebrow">${builder?'YOUR STRATEGY STARTS HERE':'YOUR FACTION COLLECTION'}</div><h2>${builder?'Build your legacy.':faction} <span class="count-pill">${builder?`${deck.length}/30`:'45 CARDS'}</span></h2><p>${builder?'Choose 30 cards. Up to 2 copies of ordinary cards, 1 of each Legendary.':'Choose your faction. Build a collection around your playstyle.'}</p></div>${!builder?`<div class="collection-stats"><span><b>${collection.filter(c=>c.type==='minion').length}</b>MINIONS</span><span><b>${collection.filter(c=>c.type==='spell').length}</b>SPELLS</span><span><b>${collection.filter(c=>c.legendary).length}</b>LEGENDARY</span></div>`:''}</section><div class="${builder?'builder-layout':''}"><section class="library">${filters()}<div class="results-label"><span>${list.length} ${filter==='tokens'?'generated tokens':'cards'} ${search?'found':'in collection'}</span><span><i class="gold-dot"></i> ${filter==='tokens'?'Tokens cannot be added to decks':'All 45 cards available to build with'}</span></div><div class="card-grid ${builder?'builder-grid':''}">${list.length?list.map(c=>card(c,{builder:builder&&filter!=='tokens'})).join(''):'<div class="empty-state">No cards match these filters.<button data-reset-filters>Clear filters</button></div>'}</div></section>${builder?deckPanel():''}</div>`;}
function deckPanel(){const ct=counts(),valid=!singleDeckProblem(faction,deck),curve=Array.from({length:8},(_,i)=>deck.filter(id=>i===7?getCard(id).cost>=7:getCard(id).cost===i).length),max=Math.max(1,...curve);return `<aside class="deck-panel"><div class="deck-cover"><span>${meta().badge}</span><h3>Your ${meta().short} deck</h3><p>30 cards · Single faction</p></div><div class="deck-inner">${heroChooser()}<label>START WITH A STRATEGY<select id="preset"><option value="">Choose a starter deck…</option>${Object.keys(presets).map(n=>`<option>${n}</option>`).join('')}</select></label><div class="deck-count"><strong>${deck.length}<small> / 30</small></strong><span class="${valid?'valid':'incomplete'}">${valid?'✓ Ready for battle':'Select your cards'}</span></div><div class="deck-progress"><i style="width:${Math.min(deck.length/30*100,100)}%"></i></div><div class="mana-curve" aria-label="Mana curve">${curve.map((n,i)=>`<div title="${i===7?'7+':i} Mana: ${n} cards"><b>${n||''}</b><i style="height:${n/max*44+2}px"></i><small>${i===7?'7+':i}</small></div>`).join('')}</div><details class="deck-contents" ${deckListOpen?'open':''}><summary>Your cards (${deck.length})</summary><div class="deck-list">${Object.keys(ct).sort((a,b)=>getCard(a).cost-getCard(b).cost).map(id=>{const c=getCard(id);return `<div class="deck-row"><span>${c.cost}</span><button data-zoom="${id}">${esc(c.name)}</button><b>${c.legendary?'✦':`×${ct[id]}`}</b><button data-remove="${id}" aria-label="Remove ${esc(c.name)}">−</button></div>`;}).join('')||'<p class="empty-deck">Add cards from the collection to shape your strategy.</p>'}</div></details><button class="primary full" data-start ${valid?'':'disabled'}>Play this deck <span>⚔</span></button><div class="deck-actions"><button data-clear>Clear deck</button><button data-export>Export</button><button data-import>Import</button></div></div></aside>`;}
function rulesHTML(){return `<section class="guide-page"><div class="eyebrow">FIELD GUIDE</div><h1>Every legend<br>starts with a <em>team.</em></h1><p class="intro">A familiar battlefield. A new world of anime.</p><div class="rules-grid">${[['01','Choose your faction','Each deck belongs to one anime faction or group. Choose Naruto, One Piece or Tokyo Ghoul. Each has a separate collection and Hero Spell.'],['02','Build a 30-card deck','Choose from 45 collectibles. Include up to 2 copies of an ordinary card and 1 copy of each Legendary. Tokens and Hero Spells stay outside your deck.'],['03','Take the battlefield','Heroes begin with 30 Health. Gain a Mana crystal each turn, up to 10. Play minions, cast Jutsu, and attack to bring the opposing Hero to 0. Your board holds 7 minions.'],['04','React with Quick Play','Substitution Jutsu and Flying Thunder God Technique are available when an enemy attacks a friendly minion. A reaction pauses combat until you respond or pass. As in the original engine, off-turn Quick Plays cost 1 less (minimum 1) and can borrow Mana from your next turn.'],['05','Use your Hero Spell','Each faction has its own 2-Mana Hero Spell, usable once per turn: Naruto’s Hero Spell summons a Shadow Clone; Nakama! buffs an ally and can heal your Hero.'],['06','Find your synergy','Build around Team 7, Luffy’s Gear evolution, permanent Devil Fruit powers, a crew of Straw Hats, or Tokyo Ghoul’s Hunger, Cannibalism and Quinque arsenal. Use the faction selector to explore all three collections.']].map(([n,h,t])=>`<article><span>${n}</span><h3>${h}</h3><p>${t}</p></article>`).join('')}</div><h2>Know your techniques</h2><div class="keywords">${Object.entries({Arrival:'Activates when played from hand. Summoned copies do not trigger Arrival.',Taunt:'Enemies must attack a Taunt minion before other characters.',Rush:'Can attack minions immediately, but must wait a turn to attack a Hero.',Evade:'Prevents the first instance of damage, then disappears.',Poisonous:'When this minion dies, the enemy that killed it dies too. This follows the original Shattered Realms keyword.',Freeze:'Cannot attack until it misses its controller’s next turn.',Legendary:'You may include at most one copy in your deck.', 'Gear Shift':'Once per turn after Luffy’s summon turn. Damage, permanent buffs, and attacks used carry over. Gear 4 branches; Gear 5 lasts three own turns, then reverts at 1 Health and rests one turn.', Hunger:'Ghouls and Half-Ghouls gain 1 Hunger at their own turn end unless they consumed this turn. At 3 or more, take 1 starvation damage. Feed costs 1 Mana and your attacks for the turn.', Cannibalism:'A Ghoul Hero gains stacks when an ally consumes a Ghoul or Half-Ghoul, up to 4. Spend 4 Mana and 4 stacks to awaken once per game and choose a second Kagune.', 'Investigator Hero':'Include one Arima, Amon or Akira Hero card in your 30-card deck to select that Hero. It starts outside the draw pile. A generic Investigator can be chosen without a Hero card.', 'Devil Fruit':'Only a non-user may consume a Fruit. Its powers and drawbacks survive Silence and keyword removal, but disappear when it leaves play. Gear forms and natural Users cannot consume Fruit.', Petrify:'Cannot attack or use activated abilities through its controller’s next turn.'}).map(([k,v])=>`<div><strong>${k}</strong><p>${v}</p></div>`).join('')}</div><p class="design-note">First-pass card designs · Minato and Hashirama retain your proposed abilities for playtesting. Temporary disabling lasts through the target’s next turn. Sasuke’s Team 7 bonus checks on Arrival; Hiruzen’s +1/+1 is an aura.</p></section>`;}

function themeFor(f){const saved=boardPreferences[f];return BOARD_THEMES[saved]?saved:f===TOKYO_GHOUL&&((page==='battle'&&state?state.players[0].tokyo?.path:TG_HEROES[selectedTGHero()].path)==='investigator')?'cochlea':boardOptions(f)[0];}
function orientationFor(){return boardOrientation==='auto'?(window.innerWidth>window.innerHeight?'landscape':'portrait'):boardOrientation;}
function boardControlsHTML(f=faction){return `<div class="board-controls"><label>Board<select id="board-theme" data-board-faction="${f}">${BOARD_KEYS.map(key=>`<option value="${key}" ${themeFor(f)===key?'selected':''}>${BOARD_THEMES[key].faction} · ${BOARD_THEMES[key].name}</option>`).join('')}</select></label><label>View<select id="board-orientation"><option value="auto" ${boardOrientation==='auto'?'selected':''}>Automatic</option><option value="portrait" ${boardOrientation==='portrait'?'selected':''}>9:16 portrait</option><option value="landscape" ${boardOrientation==='landscape'?'selected':''}>16:9 landscape</option></select></label><label>Effects<select id="board-quality">${['auto','high','low'].map(q=>`<option value="${q}" ${boardQuality===q?'selected':''}>${q==='auto'?'Automatic':q==='high'?'Full effects':'Light effects'}</option>`).join('')}</select></label><button data-board-sound aria-pressed="${boardSound}">${boardSound?'Sound on':'Sound off'}</button>${page==='boards'?`<button data-board-outlines aria-pressed="${boardDebug}">Interaction outlines</button>`:''}</div>`;}
function boardStudioHTML(){const orientation=orientationFor(),key=themeFor(faction);return `<section class="board-studio"><div class="eyebrow">YOUR BATTLEFIELD</div><h1>Bring the board to life.</h1><p>Explore your decks’ worlds. Tap objects around the edges to discover their reactions.</p>${factionPicker()}<div class="tabs"><button data-asset-tab="boards" class="${assetTab==='boards'?'selected':''}">Interactive boards</button><button data-asset-tab="frames" class="${assetTab==='frames'?'selected':''}">Card frames & heroes</button></div>${assetTab==='boards'?`${boardControlsHTML()}<div class="board-stage" data-orientation="${orientation}"><div class="board-art-mount" data-theme="${key}" data-orientation="${orientation}"></div></div><div class="board-help">${BOARD_THEMES[key].name} · ${orientation==='portrait'?'9:16':'16:9'} · Tap the corners. The center stays clear.</div>`:`<div class="portrait-gallery">${PLAYABLE_FACTIONS.map(f=>`<figure><img src="${meta(f).portrait}" alt="${f} Hero portrait"><figcaption>${f}</figcaption></figure>`).join('')}</div><div class="frame-gallery">${Object.entries(CARD_FRAMES).map(([name,frame])=>{const label=name.replace('one-piece','One Piece').replace('naruto','Naruto').replace('basic','Basic').replaceAll('-',' '),f=name.startsWith('one-piece')?STRAW_HATS:LEAF;return `<figure><button class="frame-sample" data-frame-preview="${name}" style="${frameVars(frame)}" aria-label="Inspect ${label} frame"><img class="sample-hero" src="${meta(f).portrait}" alt=""><img class="sample-overlay" src="${frame.src}" alt="${label} card frame"></button><figcaption>${label}</figcaption></figure>`;}).join('')}</div>`}</section>`;}
function hydrateBoard(){const host=$('.board-art-mount');if(!host){mountScene(null);return;}const scene=mountScene(host,{theme:host.dataset.theme,orientation:host.dataset.orientation,sound:boardSound,debug:boardDebug,quality:boardQuality});scene?.setActivity(page==='battle'&&!!(selected||state?.pending));scene?.ready.catch(()=>{});}

function equipmentHTML(pl,actions,turn){if(!pl.tokyo)return '';const w=pl.hero.weapon;return `<div class="tg-equipment">${w?`<img src="art/tokyo-ghoul/${pl.tokyo.evolved?'hybrid_kakuja':w.cardId.slice(3)}.webp" alt=""><div><strong>${esc(w.name)}</strong><small>⚔ ${w.attack} · Durability ${w.durability} / ${w.maxDurability}${w.exhausted?' · Exhausted — repair to attack':''}</small></div><button class="ghost" data-character="${pl.hero.uid}" ${turn!==0||!actions.some(a=>a.type==='attack'&&a.attacker===pl.hero.uid)?'disabled':''}>Hero attack</button>`:'<span>No Quinque equipped. Use your Hero Spell to discover one from your deck.</span>'}<small>${pl.traps.length} / 3 traps active</small></div>`;}
function legal(){return state?getLegalActions(state):[];}
function battleLobby(){return `<section class="battle-lobby"><div class="eyebrow">THE TRAINING GROUNDS</div><h1>Your next chapter<br>begins in <em>battle.</em></h1><p>Take your ${meta().short} deck into a match against a practice rival.</p><div class="lobby-card"><div class="lobby-portrait" style="background-image:url('${meta().portrait}')"></div><div><span class="eyebrow">${faction.toUpperCase()}</span><h2>${meta().title}</h2><p>30 Health · 30 cards · 1 Hero Spell</p>${heroChooser()}<label class="rival-label">Rival strategy<select id="rival-preset">${PLAYABLE_FACTIONS.map(f=>`<optgroup label="${f}">${Object.keys(ANIME_PRESETS[f]).map(n=>`<option value="${f}|${n}">${n}</option>`).join('')}</optgroup>`).join('')}</select></label><button class="primary" data-start ${singleDeckProblem(faction,deck)?'disabled':''}>Start practice match <span>⚔</span></button>${singleDeckProblem(faction,deck)?'<p class="form-error">Finish your 30-card deck in the deck builder first.</p>':''}</div></div>${state&&!state.gameOver?'<button class="ghost" data-resume>Resume your saved match →</button>':''}<p class="practice-note">Local practice · Progress saves in this browser</p></section>`;}
function charButton(m,p,valids){const c=getCard(m.cardId),active=selected?.kind==='attack'&&selected.uid===m.uid;return `<button class="unit ${valids.includes(m.uid)?'targetable':''} ${active?'unit-selected':''} ${allKeywords(m).includes('Taunt')?'taunt':''}" data-character="${m.uid}" title="${esc(c.name)}: ${esc(c.text)}${isFruitUser(m)?' Devil Fruit User. Cannot consume another Fruit.':''}"><img src="${c.image}" alt="${esc(c.name)}"><span class="unit-name">${esc(c.name)}</span><span class="unit-keywords">${allKeywords(m).map(k=>k==='Evade'?'◈':k==='Taunt'?'⛨':k==='Rush'?'↯':k==='Frozen'?'❄':k).join(' ')}${m.animeBlocks?.length||m.petrified?.length?' ⊘':''}${isFruitUser(m)?' ◈':''}${m.gear5Remaining?' · '+m.gear5Remaining+' turns':''}${m.hunger!=null?' · Hunger '+m.hunger:''}</span>${m.hunger!=null?`<span class="hunger-indicator ${m.hunger>=3?"starving":""}" title="Hunger: ${m.hunger}">◈ ${m.hunger}</span>`:""}<span class="unit-stats"><b>⚔ ${effectiveAttack(m)}</b><b class="health ${m.health<m.maxHealth?'damaged':''}">♥ ${m.health}</b></span></button>`;}
function abilitiesHTML(actions,turn){if(turn!==0)return '';return `<div class="activated-abilities">${actions.filter(a=>a.type==='gearShift').map(a=>{const m=state.players[0].board.find(m=>m.uid===a.minion);return `<button class="primary" data-gear="${a.minion}">Gear Shift · ${gearCost(m)} Mana</button>`;}).join('')}${[...new Set(actions.filter(a=>a.type==='feed').map(a=>a.minion))].map(uid=>`<button class="ghost" data-feed="${uid}">Feed · ${esc(getCard(state.players[0].board.find(m=>m.uid===uid).cardId).name)} · 1 Mana</button>`).join('')}${actions.some(a=>a.type==='kakuja')?'<button class="primary" data-kakuja>Awaken Kakuja · 4 Mana</button>':''}${[...new Set(actions.filter(a=>a.type==='lawSwap').map(a=>a.minion))].map(uid=>`<button class="ghost" data-law="${uid}">Law · Swap positions</button>`).join('')}</div>`;}
function battleHTML(){if(!state)return battleLobby();const actions=legal(),me=state.players[0],enemy=state.players[1],turn=actingPlayer(state),pend=state.pending;const sceneTheme=themeFor(me.factions[0]),sceneOrientation=orientationFor(),scene=boardVariant(sceneTheme,sceneOrientation),playStyle=`--play-l:${scene.play[0]*100}%;--play-t:${scene.play[1]*100}%;--play-w:${scene.play[2]*100}%;--play-h:${scene.play[3]*100}%`;
 const options=selected?.kind==='law'?actions.filter(a=>a.type==='lawSwap'&&a.minion===selected.uid&&(!selected.first||a.target===selected.first||a.target2===selected.first)):selected?.kind==='feed'?actions.filter(a=>a.type==='feed'&&a.minion===selected.uid):selected?.kind==='card'?actions.filter(a=>['play','quickPlay','heroSpell'].includes(a.type)&&a.card===selected.uid&&(selected.first==null||a.target===selected.first)):selected?.kind==='attack'?actions.filter(a=>a.type==='attack'&&a.attacker===selected.uid):[];
 const valids=options.flatMap(a=>selected?.kind==='law'?[a.target,a.target2].filter(x=>x!==selected.first):[selected?.kind==='card'&&selected.first!=null?a.target2:a.target??a.defender]).filter(x=>x!=null);
 const status=state.gameOver?(state.winner===0?'Victory! The Will of Fire lives on.':state.winner===null?'A hard-fought draw.':'Defeat. A new strategy awaits.'):pend?.type==='reaction'?(turn===0?'Quick Play · An ally is under attack':'Rival is considering a reaction…'):pend?.type==='choice'?(turn===0?pend.prompt:'Rival is choosing…'):pend?.type==='mulligan'?'Choose your opening hand':turn===0?'Your turn':'Rival’s turn';
 const hero=(pl,p)=>`<button class="battle-hero ${valids.includes(pl.hero.uid)?'targetable':''}" data-character="${pl.hero.uid}"><img src="${pl.tokyo?TG_HEROES[pl.tokyo.hero].image:p===0?meta(pl.factions[0]).portrait:meta(pl.factions[0]).rival}" alt="${p===0?'Your Hero':'Rival Hero'}"><span>${p===0?'You':'Practice rival'}<small>${esc(pl.tokyo?TG_HEROES[pl.tokyo.hero].name:pl.factions[0])}${pl.tokyo?' · '+(pl.tokyo.path==='ghoul'?(pl.tokyo.evolved?'Kakuja':pl.tokyo.stacks+'/4 Cannibalism'):'Investigator'):''}</small></span><b>♥ ${pl.hero.health}${pl.hero.armor?` <small>⛨ ${pl.hero.armor}</small>`:''}${effectiveAttack(pl.hero)?` <small>⚔ ${effectiveAttack(pl.hero)}</small>`:''}</b></button>`;
 return `<section class="battle-screen"><div class="battle-top"><div><div class="eyebrow">${esc(me.factions[0].toUpperCase())} · PRACTICE MATCH</div><h2>The training grounds</h2></div><button class="subtle" data-concede>${state.gameOver?'Return to collection':'Leave match'}</button></div>${boardControlsHTML(me.factions[0])}<div class="battlefield board-stage" data-orientation="${sceneOrientation}" style="${playStyle}"><div class="board-art-mount" data-theme="${sceneTheme}" data-orientation="${sceneOrientation}"></div><div class="scene-game-overlay"><div class="battle-opponent">${hero(enemy,1)}<div class="opponent-info"><span>✦ ${enemy.mana.current} / ${enemy.mana.max} Mana</span><span>▤ ${enemy.hand.length} in hand · ${enemy.deck.length} in deck</span></div><div class="card-backs">${enemy.hand.map(()=>`<i style="background-image:url('${meta(enemy.factions[0]).back}')"></i>`).join('')}</div></div><div class="battle-play-area"><div class="board-row enemy-row">${enemy.board.map(m=>charButton(m,1,valids)).join('')||'<span class="empty-board">The rival’s battlefield</span>'}</div><div class="turn-strip"><span class="${turn===0?'your-turn':''}"><i></i>${esc(status)}</span><span>TURN ${state.turn||'—'}</span>${pend?.type==='reaction'&&turn===0?'<button class="primary small" data-pass>Pass reaction →</button>':!pend&&!state.gameOver?`<button class="primary small" data-end ${turn!==0?'disabled':''}>End turn →</button>`:''}</div><div class="board-row friendly-row">${me.board.map(m=>charButton(m,0,valids)).join('')||'<span class="empty-board">Your crew assembles here</span>'}</div></div></div></div><div class="battle-player game-hud">${hero(me,0)}<button class="hero-spell ${actions.some(a=>a.type==='heroSpell')&&turn===0?'ready':''}" data-hero-spell ${!actions.some(a=>a.type==='heroSpell')||turn!==0?'disabled':''}><span>2</span>${me.tokyo?`<img class="hero-power-art" src="${getCard(me.heroSpells[0].cardId).image}" alt="">`:""}<div>${esc(getCard(me.heroSpells[0].cardId).name)}<small>${esc(getCard(me.heroSpells[0].cardId).text)} · Once per turn</small></div>✧</button><div class="mana-display"><b>✦ ${me.mana.current}<small> / ${me.mana.max}</small></b><div>${Array.from({length:10},(_,i)=>`<i class="${i<me.mana.current?'filled':i<me.mana.max?'spent':''}"></i>`).join('')}</div><small>${me.deck.length} cards in deck</small></div></div>
 ${equipmentHTML(me,actions,turn)}${abilitiesHTML(actions,turn)}<div class="placement-control"><label>Summon position <select id="placement"><option value="end">Right end</option>${me.board.map((m,i)=>`<option value="${i}" ${placement===String(i)?'selected':''}>Before ${esc(getCard(m.cardId).name)}</option>`).join('')}</select></label></div><div class="action-hint" role="status">${selected?`${selected.kind==='attack'?'Choose a highlighted target to attack.':'Choose a highlighted target.'} <button data-cancel>Cancel</button>`:state.gameOver?'Match complete. Start another match to try a different strategy.':'Tap a glowing card to play, or a ready minion to attack. Use + for details. Swipe through your hand.'}</div><div class="hand">${me.hand.map(inst=>card(getCard(inst.cardId),{compact:true,inst,valid:turn===0&&actions.some(a=>a.card===inst.uid&&['play','quickPlay'].includes(a.type))})).join('')}</div><details class="battle-log"><summary>Battle log <span>${state.log.length} events</span></summary><div>${state.log.slice(-60).reverse().map(t=>`<p>${esc(typeof t==='string'?t:t.text??JSON.stringify(t))}</p>`).join('')}</div></details>${state.gameOver?'<div class="match-finish"><button class="primary" data-new-match>Play again →</button><button class="ghost" data-nav="decks">Adjust your deck</button></div>':''}</section>${pend?.type==='mulligan'&&turn===0?`<div class="modal-shade"><section class="modal mulligan"><div class="eyebrow">A STRONG OPENING</div><h2>Choose your starting hand</h2><p>Select any cards you want to replace.</p><div class="mulligan-cards">${me.hand.map(i=>`<div role="button" tabindex="0" data-mull="${i.uid}" class="${mulligan.includes(i.uid)?'marked':''}">${card(getCard(i.cardId),{compact:true})}<span>${mulligan.includes(i.uid)?'↻ REPLACE':'KEEP'}</span></div>`).join('')}</div><button class="primary" data-keep>${mulligan.length?`Replace ${mulligan.length} cards`:'Keep this hand'} →</button></section></div>`:pend?.type==='choice'&&turn===0?`<div class="modal-shade"><section class="modal choice-modal"><div class="eyebrow">YOUR DECISION</div><h2>${esc(pend.prompt)}</h2><div class="choice-options">${pend.options.map((o,i)=>`<button class="ghost" data-choice="${i}">${esc(o.label)}</button>`).join('')}</div></section></div>`:''}`;
}
function render(){if(performance.now()<scrollingUntil){clearTimeout(renderAfterScroll);renderAfterScroll=setTimeout(render,Math.max(20,scrollingUntil-performance.now()+30));return;}restoringScroll=true;const scrollY=scrollRoot().scrollTop,handX=$('.hand')?.scrollLeft??0,listY=$('.deck-list')?.scrollTop??0,logOpen=$('.battle-log')?.open??false;const focused=document.activeElement?.id, pos=focused==='search'?$('#search')?.selectionStart:null;
 $('#app').innerHTML=`${header()}<main class="main ${page==='battle'?'battle-main':''}">${page==='collection'?collectionHTML():page==='decks'?collectionHTML(true):page==='rules'?rulesHTML():page==='boards'?boardStudioHTML():battleHTML()}<footer><span>ANIME CLASH <b>·</b> THE FIRST CHAPTER</span><span>A new legend begins with you. 🍃</span></footer></main>`;
 if(focused==='search'){$('#search').focus({preventScroll:true});$('#search').setSelectionRange(pos,pos);}bind();hydrateBoard();if($('.hand'))$('.hand').scrollLeft=handX;if($('.deck-list'))$('.deck-list').scrollTop=listY;if($('.battle-log'))$('.battle-log').open=logOpen;scrollRoot().scrollTop=scrollY;requestAnimationFrame(()=>{restoringScroll=false;});fitCardText();if(zoom)showZoom(zoom);driveAI();
}
function fitCardText(){document.querySelectorAll('.rules-parchment p').forEach(el=>{let size=parseFloat(getComputedStyle(el).fontSize);while(el.scrollHeight>el.clientHeight+1&&size>6){size-=.3;el.style.setProperty('font-size',size+'px','important');}});}
function changeDeck(id,delta){const c=getCard(id);if(delta>0&&c.investigatorHero&&deck.some(x=>getCard(x).investigatorHero)){toast('Choose only one Investigator Hero card.');return;}if(c.investigatorHero){tgHero='investigator';save('tg-hero',tgHero);}const n=counts()[id]??0;if(delta>0&&(deck.length>=30||n>=copyLimit(id)))return;if(delta<0){const i=deck.indexOf(id);if(i>=0)deck.splice(i,1);}else deck.push(id);persistDeck();render();}
function navigate(to){page=to;selected=null;zoom=null;resetPageScroll();render();}
function startMatch(){const result=checkDeck({format:'single',factions:[faction],deck,...(faction===TOKYO_GHOUL?{hero:selectedTGHero()}:{})});if(result.error){toast(result.error);return;}
 const [rivalFaction,rivalName]=($('#rival-preset')?.value??`${faction}|${Object.keys(presets)[0]}`).split('|');
 state=createGame({players:[{name:'You',factions:[faction],deck:[...deck],...(faction===TOKYO_GHOUL?{hero:selectedTGHero()}:{})},{name:'Practice rival',factions:[rivalFaction],deck:[...ANIME_PRESETS[rivalFaction][rivalName]]}],seed:Date.now()});selected=null;mulligan=[];save('match',state);page='battle';location.hash='battle';render();}

function act(action){if(!action)return;try{if(action.player===0&&action.type==='play'&&placement!=='end'){const inst=state.players[0].hand.find(i=>i.uid===action.card);if(inst&&getCard(inst.cardId).type==='minion')action={...action,position:Number(placement)};}applyAction(state,action);placement='end';selected=null;save('match',state);render();}catch(error){console.error(error);toast('That action is no longer available. Please choose again.');selected=null;render();}}
function driveAI(){clearTimeout(aiTimer);if(page!=='battle'||!state||state.gameOver||actingPlayer(state)!==1)return;aiTimer=setTimeout(()=>{try{act(chooseAction(state));}catch(e){console.error(e);toast('The rival could not choose an action. Your match is saved.');}},400);}
function selectCard(uid,hero=false){if(!state||actingPlayer(state)!==0)return;const options=legal().filter(a=>a.card===uid&&['play','quickPlay','heroSpell'].includes(a.type));if(!options.length){toast(getCard(hero?uid:state.players[0].hand.find(i=>i.uid===uid)?.cardId).reactionOnly?'This Quick Play is available when an ally is attacked.':'This card cannot be played right now.');return;}
 if(options.length===1&&options[0].target==null)act(options[0]);else{selected={kind:'card',uid};render();}}
function onCharacter(uid){if(actingPlayer(state)!==0)return;const options=legal();if(selected){if(selected.kind==='feed'){const feed=options.find(a=>a.type==='feed'&&a.minion===selected.uid&&a.target===uid);if(feed){act(feed);return;}}if(selected.kind==='card'){const cardOptions=options.filter(a=>['play','quickPlay','heroSpell'].includes(a.type)&&a.card===selected.uid);if(selected.first==null&&cardOptions.some(a=>a.target===uid&&a.target2!=null)){selected.first=uid;render();return;}if(selected.first!=null){const dual=cardOptions.find(a=>a.target===selected.first&&a.target2===uid);if(dual){act(dual);return;}return;}}if(selected.kind==='law'){if(!selected.first){if(!options.some(a=>a.type==='lawSwap'&&(a.target===uid||a.target2===uid)))return;selected.first=uid;render();return;}const swap=options.find(a=>a.type==='lawSwap'&&a.minion===selected.uid&&((a.target===selected.first&&a.target2===uid)||(a.target2===selected.first&&a.target===uid)));if(swap){act(swap);return;}}const action=selected.kind==='attack'?options.find(a=>a.type==='attack'&&a.attacker===selected.uid&&a.defender===uid):options.find(a=>['play','quickPlay','heroSpell'].includes(a.type)&&a.card===selected.uid&&a.target===uid);if(action){act(action);return;}}
 if(options.some(a=>a.type==='attack'&&a.attacker===uid)){selected={kind:'attack',uid};render();}else if(!selected){const m=state.players.flatMap(p=>p.board).find(m=>m.uid===uid);if(m){zoomUnit=m.uid;showZoom(m.cardId);};}}

// Card text with its keywords and key phrases picked out (keywords in red, triggers in purple, numbers in bold).
const KW_WORDS=['Devil Fruit User','Ignores Taunt','Quick Play','Gear Shift','Lifesteal','Drawback','Elusive','Silence','Stealth','Arrival','Reborn','Freeze','Poison','Taunt','Evade','Burn','Rush','Exit','Jutsu','Weather','Summon','Transform'];
const KW_TRIG=['At the start of your turn','At the end of your turn','at the start of your turn','at the end of your turn','Once per turn','once per turn','Whenever','If'];
const KW_RE=new RegExp(`(${[...KW_WORDS,...KW_TRIG].map(w=>w.replace(/ /g,'\\s')).join('|')})(?![a-z])|([+-]\\d+\\/[+-]\\d+|[+-]\\d+\\s(?:Attack|Health)|\\d+\\s(?:damage|Mana|Health|cards?))`,'g');
const KW_SET=new Set(KW_WORDS);
function richText(text){return esc(text??'').replace(KW_RE,(m,word,num)=>word?`<b class="${KW_SET.has(word.replace(/\s/g,' '))?'kw':'kw-trig'}">${word}</b>`:`<b class="kw-num">${num}</b>`);}
function showZoom(id){
 const previous=document.querySelector('.inspect-shade'),returnFocus=previous?.returnFocus??document.activeElement;previous?.remove();zoom=id;
 const c=getCard(id),liveUnit=state?.players.flatMap(p=>p.board).find(m=>m.uid===zoomUnit&&m.cardId===id),wrap=document.createElement('div');wrap.className='modal-shade inspect-shade';wrap.returnFocus=returnFocus;
 wrap.innerHTML=`<section class="modal inspect-modal framed-inspect" role="dialog" aria-modal="true" aria-label="${esc(c.name)}"><button class="modal-close" aria-label="Close card details">×</button>${card(c)}<div class="inspect-caption"><strong class="inspect-card-name">${esc(c.name)}</strong><span>${esc(c.faction)} · ${c.token?'Generated token':c.heroSpell?'Hero Spell':`Deck limit: ${copyLimit(c.id)} ${c.legendary?'copy':'copies'}`}</span>${liveUnit?.devilFruit?`<div class="fruit-detail"><strong>Permanent Fruit powers & drawback</strong><p>${richText(getCard('op_'+liveUnit.devilFruit.kind).text)}</p></div>`:''}</div></section>`;
 document.body.append(wrap);wrap.querySelector('.art-inspect')?.remove();
 const close=()=>{zoom=null;zoomUnit=null;wrap.remove();if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true});};wrap.querySelector('.modal-close').onclick=close;wrap.onclick=e=>{if(e.target===wrap)close();};wrap.addEventListener('keydown',e=>{if(e.key==='Escape'){e.stopPropagation();close();}if(e.key==='Tab'){e.preventDefault();wrap.querySelector('.modal-close').focus({preventScroll:true});}});fitRulesText(wrap);fitCardNames(wrap);wrap.querySelector('.modal-close').focus({preventScroll:true});
}
function bind(){
 document.querySelectorAll('[data-asset-tab]').forEach(el=>el.onclick=()=>{assetTab=el.dataset.assetTab;render();});
 document.querySelectorAll('[data-frame-preview]').forEach(el=>el.onclick=()=>{const name=el.dataset.framePreview,frame=CARD_FRAMES[name],shade=document.createElement('div');shade.className='modal-shade';shade.innerHTML=`<section class="modal frame-inspector" role="dialog" aria-modal="true" aria-label="Card frame"><button class="modal-close" aria-label="Close frame">×</button><img src="${frame.src}" alt="${name.replaceAll('-',' ')} card frame"></section>`;document.body.append(shade);shade.querySelector('button').onclick=()=>shade.remove();shade.onclick=e=>{if(e.target===shade)shade.remove();};});
 const theme=$('#board-theme');if(theme)theme.onchange=e=>{boardPreferences[theme.dataset.boardFaction]=e.target.value;save('board-preferences',boardPreferences);render();};
 const orientation=$('#board-orientation');if(orientation)orientation.onchange=e=>{boardOrientation=e.target.value;save('board-orientation',boardOrientation);render();};
 const quality=$('#board-quality');if(quality)quality.onchange=e=>{boardQuality=e.target.value;save('board-quality',boardQuality);currentScene()?.setQuality(boardQuality);};
 const sound=$('[data-board-sound]');if(sound)sound.onclick=()=>{boardSound=!boardSound;save('board-sound',boardSound);currentScene()?.setSound(boardSound);render();};
 const outlines=$('[data-board-outlines]');if(outlines)outlines.onclick=()=>{boardDebug=!boardDebug;currentScene()?.setDebug(boardDebug);render();};
 document.querySelectorAll('[data-faction]').forEach(el=>el.onclick=()=>setFaction(el.dataset.faction));
 document.querySelectorAll('[data-gear]').forEach(el=>el.onclick=()=>act(legal().find(a=>a.type==='gearShift'&&a.minion===Number(el.dataset.gear))));
 document.querySelectorAll('[data-law]').forEach(el=>el.onclick=()=>{selected={kind:'law',uid:Number(el.dataset.law)};render();});
 const contents=$('.deck-contents');if(contents)contents.ontoggle=()=>{deckListOpen=contents.open;};
 document.querySelectorAll('[data-nav]').forEach(el=>el.onclick=()=>{location.hash=el.dataset.nav;});
 document.querySelectorAll('[data-filter]').forEach(el=>el.onclick=()=>{filter=el.dataset.filter;render();});
 document.querySelectorAll('[data-mana]').forEach(el=>el.onclick=()=>{mana=el.dataset.mana;render();});
 document.querySelectorAll('[data-add]').forEach(el=>el.onclick=()=>changeDeck(el.dataset.add,1));
 document.querySelectorAll('[data-remove]').forEach(el=>el.onclick=()=>changeDeck(el.dataset.remove,-1));
 document.querySelectorAll('[data-zoom]').forEach(el=>el.onclick=e=>{e.stopPropagation();zoomUnit=null;showZoom(el.dataset.zoom);});
 document.querySelectorAll('[data-start]').forEach(el=>el.onclick=startMatch);
 document.querySelectorAll('[data-character]').forEach(el=>el.onclick=()=>onCharacter(Number(el.dataset.character)));
 document.querySelectorAll('[data-hand]').forEach(el=>{el.onclick=()=>selectCard(Number(el.dataset.hand));el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();el.click();}};});
 document.querySelectorAll('[data-mull]').forEach(el=>{el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();el.click();}};el.onclick=()=>{const id=Number(el.dataset.mull);mulligan=mulligan.includes(id)?mulligan.filter(x=>x!==id):[...mulligan,id];render();};});
 document.querySelectorAll('[data-choice]').forEach(el=>el.onclick=()=>act(legal().find(a=>a.type==='choose'&&a.index===Number(el.dataset.choice))));
 const on=(selector,event,fn)=>{const el=$(selector);if(el)el[event]=fn;};
 on('#placement','onchange',e=>{placement=e.target.value;});
 on('#search','oninput',e=>{search=e.target.value;render();});on('#sort','onchange',e=>{sort=e.target.value;render();});
 on('#preset','onchange',e=>{if(!presets[e.target.value])return;deck=[...presets[e.target.value]];persistDeck();render();toast('Starter deck loaded. Customize it to make it yours.');});
 on('[data-clear]','onclick',()=>{deck=[];persistDeck();render();});
 on('[data-reset-filters]','onclick',()=>{search='';filter='all';mana='all';render();});
 on('[data-hero-spell]','onclick',()=>selectCard(state.players[0].heroSpells[0].cardId,true));
 on('#tg-hero','onchange',e=>{tgHero=e.target.value;save('tg-hero',tgHero);render();});
 on('[data-kakuja]','onclick',()=>act(legal().find(a=>a.type==='kakuja')));
 document.querySelectorAll('[data-feed]').forEach(el=>el.onclick=()=>{selected={kind:'feed',uid:Number(el.dataset.feed)};render();});
 on('[data-end]','onclick',()=>act(legal().find(a=>a.type==='endTurn')));on('[data-pass]','onclick',()=>act(legal().find(a=>a.type==='pass')));
 on('[data-keep]','onclick',()=>{const replace=[...mulligan];mulligan=[];act({type:'mulligan',player:0,replace});});
 on('[data-cancel]','onclick',()=>{selected=null;render();});
 on('[data-concede]','onclick',()=>{if(state.gameOver){state=null;save('match',null);location.hash='collection';render();return;}const shade=document.createElement('div');shade.className='modal-shade';shade.innerHTML='<section class="modal choice-modal"><h2>Leave this match?</h2><p>Your match is saved automatically. You can return to it later.</p><div class="choice-options"><button class="primary" data-leave>Leave match</button><button class="ghost" data-stay>Keep playing</button></div></section>';document.body.append(shade);shade.querySelector('[data-leave]').onclick=()=>{shade.remove();location.hash='collection';};shade.querySelector('[data-stay]').onclick=()=>shade.remove();});
 on('[data-new-match]','onclick',()=>{state=null;save('match',null);render();});on('[data-resume]','onclick',()=>render());
 on('[data-export]','onclick',()=>{const blob=new Blob([JSON.stringify({game:'anime-clash',version:1,faction,cards:deck,...(faction===TOKYO_GHOUL?{hero:selectedTGHero()}:{})},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=faction.toLowerCase().replaceAll(' ','-')+'-deck.json';a.click();URL.revokeObjectURL(url);});
 on('[data-import]','onclick',()=>{const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const data=JSON.parse((await input.files[0].text()).replaceAll('Hidden Leaf Village','Naruto').replaceAll('Straw Hat Pirates','One Piece'));const error=singleDeckProblem(data.faction,data.cards);if(error){toast(error);return;}if(data.faction!==faction)setFaction(data.faction);deck=[...data.cards];if(data.faction===TOKYO_GHOUL&&TG_HEROES[data.hero]){tgHero=data.hero;save('tg-hero',tgHero);}persistDeck();render();toast('Deck imported.');}catch{toast('Choose a valid deck JSON file.');}};input.click();});
}
window.addEventListener('hashchange',()=>{const to=location.hash.slice(1);navigate(['collection','decks','battle','boards','rules'].includes(to)?to:'collection');});
window.addEventListener('keydown',e=>{if(e.key==='Escape'){selected=null;zoom=null;document.querySelector('.inspect-shade')?.remove();render();}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)){e.preventDefault();$('#search')?.focus();}});
page=['collection','decks','battle','boards','rules'].includes(location.hash.slice(1))?location.hash.slice(1):'collection';render();

let touchOrigin=null,ignoreClickUntil=0;
document.addEventListener('touchstart',e=>{const t=e.touches[0];touchOrigin=t?{x:t.clientX,y:t.clientY}:null;},{passive:true});
document.addEventListener('touchmove',e=>{const t=e.touches[0];if(touchOrigin&&t&&Math.hypot(t.clientX-touchOrigin.x,t.clientY-touchOrigin.y)>10)ignoreClickUntil=Date.now()+350;},{passive:true});
document.addEventListener('click',e=>{if(Date.now()<ignoreClickUntil){e.preventDefault();e.stopImmediatePropagation();}},true);

// The game owns its scroll container even inside itch.io's non-scrolling iframe.
// Do not prevent any touchstart/touchmove default; Safari needs native panning.
scrollRoot().addEventListener('scroll',()=>{if(!restoringScroll)scrollingUntil=performance.now()+140;},{passive:true});

let boardResizeTimer;window.addEventListener('resize',()=>{clearTimeout(boardResizeTimer);boardResizeTimer=setTimeout(()=>{const host=$('.board-art-mount');if(boardOrientation==='auto'&&host&&host.dataset.orientation!==orientationFor())render();},180);},{passive:true});

// Card rules text always fits inside its parchment: shrink the text a step at a time until it does
// (fonts render a little larger on some phones, which used to push lines above the box).
function fitRulesText(root=document){root.querySelectorAll('.rules-parchment p').forEach(p=>{p.style.fontSize='';const box=p.parentElement;if(!box||!box.clientHeight)return;let size=parseFloat(getComputedStyle(p).fontSize);for(let i=0;i<14&&p.scrollHeight>box.clientHeight+1;i++){size*=.93;p.style.setProperty('font-size',size+'px','important');}});}
function fitCardNames(root=document){root.querySelectorAll('.realm-card h3').forEach(title=>{const text=title.querySelector('.card-name-text');if(!text||!title.clientHeight)return;title.style.removeProperty('font-size');let size=parseFloat(getComputedStyle(title).fontSize);for(let i=0;i<20&&(text.scrollHeight>title.clientHeight||text.scrollWidth>title.clientWidth);i++){size*=.96;title.style.setProperty('font-size',size+'px','important');}});}
let fitQueued=false;const queueFit=()=>{if(fitQueued)return;fitQueued=true;requestAnimationFrame(()=>{fitQueued=false;fitRulesText();fitCardNames();});};
new MutationObserver(queueFit).observe(document.body,{childList:true,subtree:true});addEventListener('resize',queueFit);document.fonts?.ready.then(queueFit);
// Collection and deck builder: tapping anywhere on a card opens it big (buttons keep their own jobs).
document.addEventListener('click',e=>{if(e.target.closest('button,a,input,select,.modal'))return;const card=e.target.closest('.card-grid .realm-card, .card-grid .new-skin');const inspect=card?.querySelector('.art-inspect');if(inspect){e.preventDefault();inspect.click();}});
